import { doc, setDoc } from "firebase/firestore";
import { db } from "../../config/firebaseConfig"; // Увери се, че Firebase е правилно настроен

/**
 * Обновява информацията "About Me" в Firebase Firestore.
 * @param {string} name - Име.
 * @param {string} specialty - Специалност.
 * @param {string} location - Локация.
 * @param {string} education - Образование.
 * @param {string} description - Описание.
 * @param {string} profileImage - URL на профилната снимка.
 * @returns {Promise<{status: number, message: string}>}
 */
export async function updateAboutMe(name, specialty, location, education, description, profileImage) {
    try {
        const docRef = doc(db, "aboutMe", "admin"); // Референция към документа в колекцията

        await setDoc(docRef, {
            name,
            specialty,
            location,
            education,
            description,
            profileImage,
        });

        return { status: 200, message: "About Me updated successfully" };
    } catch (error) {
        console.error("Error updating About Me:", error);
        return { status: 500, message: error.message };
    }
}
